using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System.Linq;
using System.IO;
using ConRoi.Investigation.V36;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            if (EditorApplication.isPlaying)
                throw new System.Exception("Edit required");
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            const string a = "Assets/Art/InvestigationV36/R102/";
            var imp = (ModelImporter)AssetImporter.GetAtPath(a + "PuppetPoseLibrary.fbx");
            imp.importAnimation = true;
            imp.animationType = ModelImporterAnimationType.Legacy;
            imp.SaveAndReimport();
            var clips = AssetDatabase.LoadAllAssetsAtPath(a + "PuppetPoseLibrary.fbx").OfType<AnimationClip>().Where(c => !c.name.StartsWith("__preview__")).ToArray();
            s.poseIcons = InvestigationContent.Alphabet.Select(c => AssetDatabase.LoadAssetAtPath<Texture2D>(a + "Poses/Pose_" + c + ".png")).ToArray();
            var order = InvestigationContent.Alphabet.Select(c => clips.Single(x => x.name.EndsWith("Pose_" + c))).ToArray();
            var g = (GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(a + "PuppetPoseLibrary.fbx"));
            g.name = "CipherPuppet_shared_pose_ID";
            g.transform.SetParent(s.transform.Find("Workshop_GDD36"), false);
            g.transform.localPosition = new Vector3(2, .95f, -2);
            g.transform.localScale = Vector3.one * .23f;
            foreach (var ani in g.GetComponentsInChildren<Animation>())
                ani.enabled = false;
            var actor = g.AddComponent<InvestigationActor>();
            actor.puppet = true;
            actor.poseClips = order;
            actor.pose = 0;
            s.cipherPuppet = actor;
            foreach (var render in g.GetComponentsInChildren<Renderer>())
                render.sharedMaterials = render.sharedMaterials.Select(m => AssetDatabase.LoadAssetAtPath<Material>(a + "Materials/" + m.name + ".mat") ?? m).ToArray();
            var tu = s.clipTu.GetComponent<InvestigationActor>();
            tu.repairClip = clips.Single(x => x.name.EndsWith("RepairBothHands"));
            EditorSceneManager.MarkSceneDirty(s.gameObject.scene);
            EditorSceneManager.SaveScene(s.gameObject.scene);
            File.WriteAllText("Test/KetQua/investigation_r102/pose-bindings.txt", string.Join("\n", clips.Select(c => c.name + " " + c.length)) + "\nIcons=" + s.poseIcons.Count(t => t) + " expected=" + InvestigationContent.Alphabet.Length);
            r.Log("15 real model icons / same FBX pose IDs bound; repair hand pose bound; scene saved.");
        }
    }
}

